import{_ as r,c as a,o as s,ag as i}from"./chunks/framework.CQuhCYrb.js";const d=JSON.parse('{"title":"Help","description":"","frontmatter":{"title":"Help"},"headers":[],"relativePath":"general/help.md","filePath":"general/help.md","lastUpdated":null}'),t={name:"general/help.md"};function n(o,e,l,c,h,p){return s(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="help" tabindex="-1">Help <a class="header-anchor" href="#help" aria-label="Permalink to &quot;Help&quot;">​</a></h1><h2 id="behavioral-health-resources-for-service-members-and-veterans" tabindex="-1">Behavioral Health Resources for Service Members and Veterans <a class="header-anchor" href="#behavioral-health-resources-for-service-members-and-veterans" aria-label="Permalink to &quot;Behavioral Health Resources for Service Members and Veterans&quot;">​</a></h2><h3 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h3><p>This wiki serves as a self-help guide and buddy aid. The official processes can sometimes be inadequate, so we aim to provide a comprehensive list of resources, guides, and tips based on community experiences.</p><h3 id="incident-response-for-crisis-situations" tabindex="-1">Incident Response for Crisis Situations <a class="header-anchor" href="#incident-response-for-crisis-situations" aria-label="Permalink to &quot;Incident Response for Crisis Situations&quot;">​</a></h3><h3 id="disclaimer" tabindex="-1">Disclaimer <a class="header-anchor" href="#disclaimer" aria-label="Permalink to &quot;Disclaimer&quot;">​</a></h3><p><em>This section is intended to provide awareness of resources and share approaches that have been effective in the past. It is not a substitute for professional medical advice. It is important to consult a healthcare professional in situations requiring medical or therapeutic intervention.</em></p><h3 id="are-you-experiencing-a-crisis" tabindex="-1">Are You Experiencing a Crisis? <a class="header-anchor" href="#are-you-experiencing-a-crisis" aria-label="Permalink to &quot;Are You Experiencing a Crisis?&quot;">​</a></h3><p>If you are in a crisis:</p><ul><li><p><strong>Immediate Help</strong>: If you are in immediate danger or need urgent medical attention, call 911 or your local emergency number.</p></li><li><p><strong>Seek Support</strong>: Reach out to a crisis line like the <a href="https://www.veteranscrisisline.net" target="_blank" rel="noreferrer">Veterans Crisis Line</a> for confidential support.</p></li><li><p><strong>Stay Safe</strong>: Find a safe space and consider reaching out to someone you trust while you wait for professional help.</p></li></ul><h3 id="is-someone-you-know-experiencing-a-crisis" tabindex="-1">Is Someone You Know Experiencing a Crisis? <a class="header-anchor" href="#is-someone-you-know-experiencing-a-crisis" aria-label="Permalink to &quot;Is Someone You Know Experiencing a Crisis?&quot;">​</a></h3><p>If you know someone who is in crisis:</p><p><a href="https://adminpubs.tradoc.army.mil/pamphlets/TP600-22.pdf" target="_blank" rel="noreferrer">Leaders Guide for Risk Reduction and Suicide Prevention</a></p><ul><li><p><strong>Physically Present</strong>: If you can safely be with the person, do so. Use the “Listen, Ask, Care, Escort” approach:</p></li><li><p><strong>Listen</strong>: Be active, show empathy, and give them your full attention.</p></li><li><p><strong>Ask</strong>: Gently ask direct questions about their well-being and if they are thinking about harming themselves.</p></li><li><p><strong>Care</strong>: Show that you care. Your concern and support can make a difference. * <strong>Escort</strong>: If necessary, escort them to professional help or call for emergency assistance.</p></li><li><p><strong>Not Physically Present</strong>: If you cannot be there in person:</p></li><li><p><strong>Stay in Contact</strong>: Message them, call them, and be available to talk. Consistent communication can be crucial.</p></li><li><p><strong>Signs of Suicidal Ideation</strong>: If they show signs of suicidal thoughts and stop responding, consider actions that can provide immediate, albeit indirect, support, such as sending comfort food or ensuring that someone can check on them physically.</p></li><li><p><strong>Professional Help</strong>: Encourage them to contact a crisis line or seek professional help. Share resources like the <a href="https://www.veteranscrisisline.net" target="_blank" rel="noreferrer">Veterans Crisis Line</a>.</p></li></ul><h3 id="just-browsing-for-crisis-and-preventative-resources" tabindex="-1">Just Browsing for Crisis and Preventative Resources <a class="header-anchor" href="#just-browsing-for-crisis-and-preventative-resources" aria-label="Permalink to &quot;Just Browsing for Crisis and Preventative Resources&quot;">​</a></h3><p>If you are looking for information: * <strong>Educate Yourself</strong>: Learn about signs of crisis, mental health issues, and preventive measures. * <strong>Be Prepared</strong>: Know how to respond to a crisis, whether it’s for yourself or someone else. * <strong>Share Knowledge</strong>: Share what you learn with others. Awareness can save lives.</p><h3 id="best-practices-for-crisis-response" tabindex="-1">Best Practices for Crisis Response <a class="header-anchor" href="#best-practices-for-crisis-response" aria-label="Permalink to &quot;Best Practices for Crisis Response&quot;">​</a></h3><ul><li><p><strong>Stay Calm</strong>: Keeping calm is crucial. It helps you think clearly and comforts the person in crisis.</p></li><li><p><strong>Non-Judgmental Approach</strong>: Avoid judgments. Listen and speak without making the person feel worse.*</p></li></ul><p><em><strong>Privacy and Respect</strong>: Respect their privacy. Avoid discussing their situation with others without their consent.</em></p><ul><li><strong>Follow-Up</strong>: After the immediate crisis, check in on them. Ongoing support can aid in their recovery.*</li></ul><p><em><strong>Self-Care</strong>: Remember to take care of your mental health. Responding to a crisis can be taxing.</em></p><h3 id="crisis-resources" tabindex="-1">Crisis Resources <a class="header-anchor" href="#crisis-resources" aria-label="Permalink to &quot;Crisis Resources&quot;">​</a></h3><h3 id="immediate-assistance" tabindex="-1">Immediate Assistance <a class="header-anchor" href="#immediate-assistance" aria-label="Permalink to &quot;Immediate Assistance&quot;">​</a></h3><h4 id="crisis-line" tabindex="-1">Crisis Line <a class="header-anchor" href="#crisis-line" aria-label="Permalink to &quot;Crisis Line&quot;">​</a></h4><ul><li><a href="https://www.veteranscrisisline.net" target="_blank" rel="noreferrer">Veterans Crisis Line</a>: Offers 24/7, confidential crisis support for veterans and their loved ones. Reachable by calling <code>988</code> and pressing <code>1</code> or via text at <code>838255</code>. Services are available for veterans, service members, National Guard and Reserve members, and their supporters, even those not enrolled in VA benefits or health care.</li></ul><h4 id="emergency-services" tabindex="-1">Emergency Services <a class="header-anchor" href="#emergency-services" aria-label="Permalink to &quot;Emergency Services&quot;">​</a></h4><h6 id="global" tabindex="-1">Global <a class="header-anchor" href="#global" aria-label="Permalink to &quot;Global&quot;">​</a></h6><ul><li><p><strong>Military OneSource</strong>: A 24/7 resource for military members, spouses, and families, offering various support services. Phone: 1-800-342-9647. <a href="https://www.militaryonesource.mil/contact-us/" target="_blank" rel="noreferrer">Online chat available here</a>.</p></li><li><p><strong>Defense Centers of Excellence (DCoE) Outreach Center</strong>: Provides resources and support for psychological health and traumatic brain injury. Phone: 1-866-966-1020. <a href="https://ourcalvert.org/services/supportive-services/defense-centers-excellence-dcoe-outreach-center" target="_blank" rel="noreferrer">Contact link</a>.*</p></li><li><p><strong>GiveAnHour</strong>: Connects individuals to local mental health providers. <a href="https://giveanhour.org" target="_blank" rel="noreferrer">Visit GiveAnHour</a>.*</p></li></ul><h3 id="counseling-and-therapy-services" tabindex="-1">Counseling and Therapy Services <a class="header-anchor" href="#counseling-and-therapy-services" aria-label="Permalink to &quot;Counseling and Therapy Services&quot;">​</a></h3><ul><li><p><strong>Military and VA Services</strong></p><ul><li><a href="https://www.mentalhealth.va.gov" target="_blank" rel="noreferrer">VA Mental Health Services</a>: Provides various mental health services through the VA.**</li></ul></li></ul><p><strong><a href="https://www.vetcenter.va.gov/" target="_blank" rel="noreferrer">VET Centers</a> Vet Centers are community-based counseling centers that provide various social and psychological services, including professional counseling to eligible Veterans, service members, including National Guard and Reserve components, and their families.</strong></p><p><em><strong>Off-Post Options</strong></em></p><p><strong>&#39; <a href="https://maketheconnection.net" target="_blank" rel="noreferrer">VA Make The Connection Program</a>: A VA program connecting veterans to mental health resources.</strong></p><ul><li>Virtual Resources*</li></ul><ul><li><a href="https://moodhacker.resilienceboost.com/tracker/landing/" target="_blank" rel="noreferrer">MWR Mood Tracker App</a></li></ul><h3 id="support-groups-and-peer-networks" tabindex="-1">Support Groups and Peer Networks <a class="header-anchor" href="#support-groups-and-peer-networks" aria-label="Permalink to &quot;Support Groups and Peer Networks&quot;">​</a></h3><ul><li><p><strong>In-Person Support Groups</strong></p></li><li><p><strong>Online Communities</strong>*</p><ul><li><p><a href="https://www.reddit.com/r/SuicideWatch/" target="_blank" rel="noreferrer">Reddit: r/suicidewatch</a>: An online community for support during suicidal crises.**</p></li><li><p><a href="https://www.reddit.com/r/army/comments/sczzhb/comment/hua5fk5/?share_id=OjlOFARUMZp-X8RQxyudT&amp;utm_content=2&amp;utm_medium=android_app&amp;utm_name=androidcss&amp;utm_source=share&amp;utm_term=20" target="_blank" rel="noreferrer">Reddit: Veteran Perspective</a>: A thread offering a veteran’s perspective on mental health support.**</p></li></ul></li></ul><h3 id="advocacy-and-legal-support" tabindex="-1">Advocacy and Legal Support <a class="header-anchor" href="#advocacy-and-legal-support" aria-label="Permalink to &quot;Advocacy and Legal Support&quot;">​</a></h3><ul><li><strong>Veterans’ Rights</strong> <strong>Support Organizations</strong>*</li></ul><p><em><strong>The Army’s Resilience Directorate</strong>: Provides a range of resources for resilience and mental health in the Army. <a href="https://www.armyresilience.army.mil" target="_blank" rel="noreferrer">Resilience Directorate Resources</a>.</em></p><h3 id="feedback-and-community-input" tabindex="-1">Feedback and Community Input <a class="header-anchor" href="#feedback-and-community-input" aria-label="Permalink to &quot;Feedback and Community Input&quot;">​</a></h3><ul><li><p><strong>Suggestion Box</strong></p></li><li><p><strong>Community Stories</strong> <em>More content to be added</em></p></li></ul><h3 id="substance-abuse-help" tabindex="-1">Substance Abuse Help <a class="header-anchor" href="#substance-abuse-help" aria-label="Permalink to &quot;Substance Abuse Help&quot;">​</a></h3><p><em>More content to be added</em></p>',44)])])}const m=r(t,[["render",n]]);export{d as __pageData,m as default};
